ght:3px;background:#26303b;border-radius:4px;margin:2px 0 8px}.progress-track i{height:100%;width:0;display:block;background:var(--mint);box-shadow:0 0 10px #a7f3d080;transition:width .3s}.mission-progress span{font:500 8px var(--mono);letter-spacing:.08em;color:#8a96a7}
.studio-grid{display:grid;grid-template-columns:minmax(370px,.91fr) minmax(440px,1.09fr);gap:14px;align-items:stretch}.panel{background:linear-gradient(145deg,rgba(19,24,34,.97),rgba(14,18,26,.98));border:1px solid var(--line);border-radius:9px;overflow:hidden;box-shadow:0 13px 35px #00000012}.editor-panel{min-height:548px;display:flex;flex-direction:column}.panel-heading{height:61px;border-bottom:1px solid #222a36;padding:0 18px;display:flex;justify-content:space-between;align-items:center;flex-shrink:0}.panel-title{display:flex;align-items:center;gap:11px}.panel-icon{width:29px;height:29px;border:1px solid #2c3944;border-radius:7px;display:grid;place-items:center;font:500 10px var(--mono)}.code-icon{color:var(--mint);background:#10231e}.world-icon{color:#94b6ff;background:#152039;font-size:18px}.panel-title h2,.terminal-heading h2{font:600 13px var(--display);margin:0 0 3px;letter-spacing:-.015em}.panel-subtitle{font:500 8px var(--mono);letter-spacing:.08em;color:#818c9d}.file-name{color:#586475;letter-spacing:0}.editor-heading-actions{display:flex;align-items:center;gap:7px}.unsaved-dot{width:5px;height:5px;background:var(--amber);border-radius:50%;opacity:0;transition:opacity .2s}.unsaved-dot.show{opacity:1}.small-icon{border:1px solid transparent;background:transparent;color:#758194;border-radius:5px;width:26px;height:25px;font-size:16px}.small-icon:hover{border-color:#303948;background:#1a202b;color:#d4deeb}.editor-wrap{position:relative;display:grid;grid-template-columns:43px 1fr;flex:1;min-height:285px;background:#0d1118;padding:15px 16px 12px 0}.line-gutter{font:12px/22px var(--mono);color:#495465;text-align:right;padding-right:12px;white-space:pre;user-select:none;overflow:hidden}.editor-wrap textarea{position:relative;z-index:1;resize:none;border:0;outline:none;background:transparent;color:#d3dbe7;caret-color:var(--mint);font:12px/22px var(--mono);padding:0 4px;white-space:pre;overflow:auto;tab-size:2;min-height:100%;width:100%;scrollbar-width:thin;scroll