ont-size:10px;color:#a4a99f;margin:3px 0 0;line-height:1.35}.tip-card button{margin-left:auto;border:0;background:transparent;color:#8d9b8e;font-size:14px}.command-row{display:flex;align-items:center;gap:5px;margin-top:10px}.command-label{font:8px var(--mono);color:#657082;letter-spacing:.08em;margin-right:4px}.command-chip{border:1px solid #2a3240;border-radius:3px;background:#151b25;padding:5px 7px;color:#9ca8b7;font:8px var(--mono);letter-spacing:.04em}.command-chip:hover{border-color:#61796f;color:var(--mint);background:#17251f}
.world-panel{min-height:548px;display:flex;flex-direction:column}.world-heading{height:61px}.sector-code{color:#c0cfdf}.world-separator{padding:0 5px;color:#505a68}.world-actions{display:flex;align-items:center;gap:11px}.world-live{display:flex;align-items:center;gap:6px;color:#81958d;font:8px var(--mono);letter-spacing:.08em}.world-live span{width:5px;height:5px}.expand-button{font-size:15px}.board-stage{position:relative;flex:1;min-height:389px;display:grid;place-items:center;overflow:hidden;background:radial-gradient(ellipse at 50% 49%,#17232d 0%,#111821 49%,#10151d 74%);background-image:linear-gradient(90deg,rgba(121,160,169,.025) 1px,transparent 1px),linear-gradient(rgba(121,160,169,.025) 1px,transparent 1px),radial-gradient(ellipse at 50% 49%,#19252e 0%,#111821 50%,#10151d 78%);background-size:27px 27px,27px 27px,auto}.board-frame{position:relative;padding:10px;border:1px solid #313d47;background:#10171e;box-shadow:0 0 0 5px #0e141b,0 16px 50px #0009;transition:transform .35s}.board-grid{--cols:7;display:grid;grid-template-columns:repeat(var(--cols),minmax(37px,52px));grid-template-rows:repeat(var(--rows,7),minmax(37px,52px));gap:3px;position:relative}.tile{position:relative;width:clamp(37px,5vw,52px);height:clamp(37px,5vw,52px);background:#1b2730;border:1px solid #263540;border-radius:3px;transition:background .22s,border .22s;display:grid;place-items:center}.tile.floor:nth-child(odd){background:#1a252e}.tile.wall{background:#0d131a;border-color:#1b2730;box-shadow:inset 0 0 14px #0007}.tile.wall:after{content:'';position:absolute;inset:4px;border:1px solid #1b252e;border-radius:2px;background:repeating-linear-gradient(135deg,#141d25 0 4px,#111820 4px 8px)}.tile.exit{background:#17281f;border-color:#33533f;box-shadow:inset 0 0 17px #3bd18d11}.exit-symbol{color:#a7f3d0;font:17px var(--display);text-shadow:0 0 11px #8bf2c0}.tile.shard-cell{background:#1c2930}.shard-gem{height:10px;width:10px;background:#ffca82;transform:rotate(45deg);border-radius:2px;box-shadow