}.legend-exit{color:#a7f3d0}.world-controls{display:flex;align-items:center;gap:6px}.speed-label{font:8px var(--mono);color:#718091;letter-spacing:.08em;margin-right:3px}.speed-button{width:16px;height:17px;padding:0;background:transparent;border:0;color:#a2aebc;font-size:13px}.speed-track{width:44px;height:3px;background:#303846}.speed-track i{display:block;width:60%;height:100%;background:#a7f3d0;transition:width .2s}
.bottom-grid{display:grid;grid-template-columns:minmax(370px,.91fr) minmax(440px,1.09fr);gap:14px;margin-top:14px}.terminal-panel{height:186px;background:#0e1219}.terminal-heading{height:50px;border-bottom:1px solid #232a36;display:flex;align-items:center;justify-content:space-between;padding:0 16px}.terminal-prompt{width:28px;height:28px;display:grid;place-items:center;border:1px solid #273440;border-radius:6px;color:#91b5a8;background:#111b1c;font:11px var(--mono)}.terminal-heading .panel-subtitle{font-size:8px}.terminal-actions{display:flex;align-items:center;gap:12px;font:8px var(--mono);letter-spacing:.06em;color:#687587}.terminal-actions button{background:transparent;border:0;color:#748194;font:8px var(--mono)}.terminal-body{height:135px;padding:10px 15px;overflow:auto;font:10px/1.65 var(--mono);scrollbar-width:thin;scrollbar-color:#39424f transparent}.terminal-empty{color:#697587;display:flex;align-items:center;gap:9px;padding-top:21px}.terminal-empty-glyph{font-size:15px;color:#849391}.log-line{display:flex;gap:10px;color:#aeb8c6;white-space:pre-wrap}.log-time{color:#5e6a7a}.log-line.ok .log-msg{color:#a1e5c4}.log-line.warn .log-msg{color:#e9cb8b}.log-line.error .log-msg{color:#ff9298}.log-line.info .log-msg{color:#a6bad7}.reference-panel{min-height:186px;padding:15px 18px 10px}.reference-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:11px}.reference-heading h2{font:600 14px var(--display);margin:4px 0 0;letter-spacing:-.03em}.reference-heading .eyebrow{font-size:8px;color:#819092}.reference-heading button{border:0;background:transparent;color:#8995a5;font-size:16px;transition:transform .2s}.reference-panel.collapsed .reference-heading button{transform:rotate(-90deg)}.reference-content{display:grid;grid-template-columns:1fr 1fr;column-gap:20px;transition:max-height .2s;overflow:hidden}.reference-panel.collapsed .reference-content{max-height:0}.reference-block{display:grid;grid-template-columns:19px auto 1fr;align-items:ce